import React, { useState, useEffect } from "react";
import { useHistory, useParams } from "react-router-dom";
import { getCarById, updateCar } from "../../services/ApiCar";

export default function CardUpdateVoiture() {
  const history = useHistory();
  const { id } = useParams();
  const [car, setCar] = useState(null);
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  useEffect(() => {
    const fetchCar = async () => {
      try {
        const data = await getCarById(id);
        setCar(data);
      } catch (error) {
        console.error("Erreur de chargement:", error);
      }
    };
    fetchCar();
  }, [id]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setCar({ ...car, [name]: value });
    if (errors[name]) setErrors({ ...errors, [name]: "" });
  };

  const handleFileChange = (e) => {
    setCar({ ...car, voiture_image: e.target.files[0] });
    if (errors.voiture_image) setErrors({ ...errors, voiture_image: "" });
  };

  const validateForm = () => {
    const formErrors = {};
    const requiredFields = ["matricule", "model", "marque", "TypeDeCarburant", "prix", "prix_jour"];

    requiredFields.forEach((field) => {
      if (!car[field]) {
        formErrors[field] = `${field} est requis`;
      }
    });

    setErrors(formErrors);
    return Object.keys(formErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;

    setIsSubmitting(true);

    const formData = new FormData();
    for (const key in car) {
      if (car[key] !== null && car[key] !== undefined) {
        formData.append(key, car[key]);
      }
    }

    try {
      await updateCar(id, formData);
      history.push("/admin/Voiture");
    } catch (error) {
      console.error("Erreur de mise à jour:", error);
      alert("Erreur lors de la mise à jour de la voiture");
    } finally {
      setIsSubmitting(false);
    }
  };

  if (!car) return <p className="text-center mt-10">Chargement...</p>;

  const carburantOptions = ["Essence", "Diesel", "Hybride", "Électrique", "GPL", "Bioéthanol"];
  const transmissionOptions = ["Manuelle", "Automatique", "Semi-automatique"];
  const categorieOptions = ["Economique", "Compacte", "Berline", "SUV", "Monospace", "Sportive", "Luxe"];

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">Modifier la voiture</h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            type="button"
            onClick={() => history.push("/admin/Voiture")}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          {/* Tu peux ici copier les mêmes champs que dans CardAddVoiture, juste remplacer "newCar" par "car" */}
          {/* Pour raccourcir, je peux te réinsérer tout le JSX si tu veux, mais tu peux vraiment juste copier/coller ton addVoiture et remplacer toutes les occurences de `newCar` par `car`, et ça marchera pareil */}

          {/* Exemple: */}
          <div className="w-full lg:w-6/12 px-4">
            <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">Matricule</label>
            <input
              type="text"
              name="matricule"
              value={car.matricule}
              onChange={handleChange}
              className="border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow w-full"
            />
            {errors.matricule && <p className="text-red-500 text-xs italic mt-1">{errors.matricule}</p>}
          </div>

          {/* ... etc pour le reste du formulaire */}

          <div className="text-center mt-6">
            <button
              type="submit"
              className={`bg-lightBlue-500 text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md ${
                isSubmitting ? "opacity-50 cursor-not-allowed" : ""
              }`}
              disabled={isSubmitting}
            >
              {isSubmitting ? "Mise à jour..." : "Mettre à jour"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
